// ─── File: SearchDemo.java ───
// Runnable mini search engine demo (illustrates what Elasticsearch does internally).
// Each class would be its own file in a real project.
package com.bank.search;

import java.util.*;
import java.util.logging.*;
import java.util.stream.Collectors;

public class SearchDemo {
    private static final Logger log = Logger.getLogger(SearchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        InvertedIndex index = new InvertedIndex();

        // Index products (normally fed asynchronously from DB events/CDC)
        index.addOrUpdate(new Product("P1", "Home Loan", "Low interest home loan for salaried", 8.50));
        index.addOrUpdate(new Product("P2", "Home Loan Plus", "Premium home loan with top-up", 8.90));
        index.addOrUpdate(new Product("P3", "Personal Loan", "Unsecured personal loan", 12.50));
        index.addOrUpdate(new Product("P4", "Fixed Deposit", "Safe fixed deposit savings", 7.00));

        // Query 1: ranked full-text search "home loan"
        log.info("Search 'home loan' (ranked):");
        index.search(new SearchQuery("home loan", null, 0, 10))
                .forEach(r -> log.info("  " + r));

        // Query 2: fuzzy — typo "houm lon" still finds home loans
        log.info("Search 'houm lon' (fuzzy, max 2 edits):");
        index.search(new SearchQuery("houm lon", null, 0, 10))
                .forEach(r -> log.info("  " + r));

        // Query 3: filtered — loans with rate < 9.0, sorted by score
        log.info("Search 'loan' filter rate<9.0:");
        index.search(new SearchQuery("loan", p -> p.rate < 9.0, 0, 10))
                .forEach(r -> log.info("  " + r));

        // Simulate async sync: rate of P1 changes in the DB → event updates the index
        IndexSyncConsumer sync = new IndexSyncConsumer(index);
        sync.onProductUpdated(new Product("P1", "Home Loan", "Low interest home loan for salaried", 8.25));
        log.info("After async rate update, search 'home loan':");
        index.search(new SearchQuery("home loan", null, 0, 1))
                .forEach(r -> log.info("  " + r));
    }
}

