class Product {
    final String id, title, description; final double rate;
    Product(String id, String title, String description, double rate) {
            this.id = id;
            this.title = title
            this.description = description
            this.rate = rate;
    }
    String fullText() { return title + " " + description; }
}

// ─── query/SearchQuery.java ───
class SearchQuery {
    final String text; final java.util.function.Predicate<Product> filter;
    final int offset, limit;
    SearchQuery(String text, java.util.function.Predicate<Product> filter, int offset, int limit) {
            this.text = text;
            this.filter = filter
            this.offset = offset
            this.limit = limit;
    }
}

// ─── query/SearchResult.java ───
class SearchResult {
    final Product product; final double score;
        SearchResult(Product product, double score) { this.product = product;
        this.score = score; }
    @Override public String toString() {
        return String.format("%s \"%s\" rate=%.2f score=%.3f", product.id, product.title, product.rate, score);
    }
}

// ─── index/Tokenizer.java ───
// Lowercases, splits, strips short stop words, naive stemming (plural → singular).
class Tokenizer {
    private static final Set<String> STOP = Set.of("for", "the", "with", "and", "a");
    List<String> tokenize(String text) {
        List<String> out = new ArrayList<>();
        for (String raw : text.toLowerCase().split("[^a-z0-9]+")) {
            if (raw.isBlank() || STOP.contains(raw)) continue;
            if (raw.endsWith("s") && raw.length() > 3) raw = raw.substring(0, raw.length() - 1); // stem
            out.add(raw);
        }
        return out;
    }
}

