// Levenshtein edit distance for typo tolerance.
class FuzzyMatcher {
    int editDistance(String a, String b) {
        int[] prev = new int[b.length() + 1];
        for (int j = 0; j <= b.length(); j++) prev[j] = j;
        for (int i = 1; i <= a.length(); i++) {
            int[] cur = new int[b.length() + 1]; cur[0] = i;
            for (int j = 1; j <= b.length(); j++) {
                int cost = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;
                cur[j] = Math.min(Math.min(cur[j - 1] + 1, prev[j] + 1), prev[j - 1] + cost);
            }
            prev = cur;
        }
        return prev[b.length()];
    }
}

// ─── index/InvertedIndex.java ───
// Core: term → posting list of doc IDs. BM25-ish scoring, fuzzy expansion, filter + paginate.
class InvertedIndex {
    private final Map<String, Set<String>> postings = new HashMap<>();   // term → doc IDs
    private final Map<String, Product> docs = new HashMap<>();           // id → product
    private final Map<String, List<String>> docTerms = new HashMap<>();  // id → its terms
    private final Tokenizer tokenizer = new Tokenizer();
    private final FuzzyMatcher fuzzy = new FuzzyMatcher();

    void addOrUpdate(Product p) {
        remove(p.id);
        List<String> terms = tokenizer.tokenize(p.fullText());
        docs.put(p.id, p);
        docTerms.put(p.id, terms);
        for (String t : terms) postings.computeIfAbsent(t, k -> new HashSet<>()).add(p.id);
    }
    void remove(String id) {
        List<String> old = docTerms.remove(id);
        if (old != null) for (String t : old) {
            Set<String> set = postings.get(t);
                if (set != null) { set.remove(id);
                if (set.isEmpty()) postings.remove(t); }
        }
        docs.remove(id);
    }

    List<SearchResult> search(SearchQuery q) {
        List<String> queryTerms = tokenizer.tokenize(q.text);
        Map<String, Double> scores = new HashMap<>();
        int totalDocs = Math.max(1, docs.size());

        for (String term : queryTerms) {
            // exact posting list, plus fuzzy-matched terms within edit distance 2
            Set<String> matchingDocs = new HashSet<>(postings.getOrDefault(term, Set.of()));
            for (String indexedTerm : postings.keySet())
                if (!indexedTerm.equals(term) && fuzzy.editDistance(term, indexedTerm) <= 2)
                    matchingDocs.addAll(postings.get(indexedTerm));

            int df = Math.max(1, matchingDocs.size());               // document frequency
            double idf = Math.log(1.0 + (double) totalDocs / df);     // rarer term = higher weight
            for (String id : matchingDocs) {
                double tf = freq(id, term);                           // term frequency in doc
                scores.merge(id, tf * idf, Double::sum);              // BM25-style accumulation
            }
        }

        return scores.entrySet().stream()
                .map(e -> new SearchResult(docs.get(e.getKey()), e.getValue()))
                .filter(r -> q.filter == null || q.filter.test(r.product))   // structured filter
                .sorted(Comparator.comparingDouble((SearchResult r) -> r.score).reversed())
                .skip(q.offset).limit(q.limit)                               // pagination
                .collect(Collectors.toList());
    }

    private double freq(String id, String term) {
        List<String> terms = docTerms.getOrDefault(id, List.of());
        long c = terms.stream().filter(t -> t.equals(term) || fuzzy.editDistance(t, term) <= 2).count();
        return (double) c;
    }
}

// ─── sync/IndexSyncConsumer.java ───
// Consumes ProductUpdated events (from Kafka/CDC) and updates the index asynchronously.
class IndexSyncConsumer {
    private static final Logger log = Logger.getLogger(IndexSyncConsumer.class.getName());
    private final InvertedIndex index;
    IndexSyncConsumer(InvertedIndex index) { this.index = index; }
    void onProductUpdated(Product p) {
        index.addOrUpdate(p);     // eventual consistency: index now reflects the DB change
        log.info("INDEX SYNCED " + p.id + " (rate now " + p.rate + ")");
    }
}

